package com.campuskart;
import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.sql.*;
@WebServlet("/login") public class LoginServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{String id=r.getParameter("studentId"),pw=r.getParameter("password");if(id==null||pw==null||id.isBlank()||pw.isBlank()){s.sendRedirect("login.jsp?error=Fill+all+fields");return;}try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT id,name,student_id FROM users WHERE student_id=? AND password_hash=?")){p.setString(1,id.trim());p.setString(2,PasswordUtil.sha256(pw));try(ResultSet x=p.executeQuery()){if(x.next()){HttpSession h=r.getSession();h.setAttribute("userId",x.getInt("id"));h.setAttribute("userName",x.getString("name"));h.setAttribute("studentId",x.getString("student_id"));s.sendRedirect("marketplace");}else s.sendRedirect("login.jsp?error=Invalid+student+ID+or+password");}}catch(SQLException e){throw new IOException(e);}}}